from pathlib import Path
import zlib,base64,hashlib,sys,subprocess,os
source=zlib.decompress(base64.b64decode(''))
assert hashlib.sha256(source).hexdigest()=='1ec05fd64270c200a79c1a01f15faf2a23df115be79f2182caa50f0fece0549a'
compile(source,'w06_source','exec')
p=Path('/home/ec2-user/studies/diet_gut_cgm_v2/multisystem_project_20261021/scripts/w06_food_cleaning_20261028')
p.mkdir(parents=True,exist_ok=True)
f=p/'01_inspect_source_contract.py'
assert not f.exists(),str(f)
f.write_bytes(source)
assert f.read_bytes()==source
r=Path('/home/ec2-user/multisystem_runtime_20261021/w06_food_cleaning_20261028')
r.mkdir(parents=True,exist_ok=True)
e=os.environ.copy();e.update(OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
with (r/'01.log').open('w') as log:
 result=subprocess.run([sys.executable,'-u',str(f)],stdout=log,stderr=subprocess.STDOUT,timeout=120,env=e)
(r/'01_actual_exit_code').write_text(str(result.returncode))
print((r/'01.log').read_text())
print('ACTUAL_EXIT',result.returncode)
